def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [a for a, b in history]
    opp = [b for a, b in history]
    opp_d = sum(1 for x in opp if x == 'D')

    # Exploit if the most recent completed defection was not retaliated
    for i in range(n - 2, -1, -1):
        if my[i] == 'D':
            if opp[i + 1] == 'C':
                return 'D'
            break

    # Defect against persistent defectors (opponent defection rate > 0.3)
    if opp_d * 10 > n * 3:
        return 'D'

    # Periodically test for an unconditional cooperator
    recent_my = my[-10:] if n >= 10 else my
    if 'D' not in recent_my and n >= 10:
        return 'D'

    return 'C'
